95		// Temperature/TopP/TopK/MinP/RepetitionPenalty are sampling controls.
96		// TopP is OpenAI-standard; TopK / MinP / RepetitionPenalty are
97		// non-standard OpenAI-compat extras that omlx, lmstudio, vLLM, and
98		// llama.cpp accept as top-level body fields. Nil means unset
99		// (server default applies). RepetitionPenalty > 1.0 prevents
100		// exact-token loops.
101		Temperature       *float64
102		TopP              *float64
103		TopK              *int
104		MinP              *float64
105		RepetitionPenalty *float64
106		Seed              int64
107		Stop              []string
