171	// ChatStream executes one streaming Chat Completions request and converts
172	// chunks into agent stream deltas.
173	func (c *Client) ChatStream(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions, hooks StreamHooks) (<-chan agent.StreamDelta, error) {
174		params := buildParams(model, messages, tools, opts)
175		params.StreamOptions = oai.ChatCompletionStreamOptionsParam{
176			IncludeUsage: oai.Bool(true),
177		}
178	
179		stream := c.client.Chat.Completions.NewStreaming(ctx, params, opts.ExtraOptions...)
180	
181		ch := make(chan agent.StreamDelta, 1)
182		go func() {
183			defer close(ch)
184			send := func(delta agent.StreamDelta) {
185				delta.ArrivedAt = time.Now()
186				ch <- delta
187			}
188	
189			// OpenAI only sends tool call ID in the first chunk for each index;
190			// subsequent argument chunks carry the index but have an empty ID.
191			indexToID := make(map[int]string)
192			responseModel := model
193			var streamCost *agent.CostAttribution
194			for stream.Next() {
195				chunk := stream.Current()
196				if chunk.Model != "" {
197					responseModel = chunk.Model
198				}
199				if hooks.Cost != nil {
200					if cost := hooks.Cost(chunk.Usage.RawJSON()); cost != nil {
201						streamCost = cost
202					}
203				}
204	
205				reasoningContent := extractReasoningContent(chunk.RawJSON())
206	
207				if len(chunk.Choices) > 0 {
208					choice := chunk.Choices[0]
209	
210					for _, tc := range choice.Delta.ToolCalls {
211						id := tc.ID
212						if id != "" {
213							indexToID[int(tc.Index)] = id
214						} else {
215							id = indexToID[int(tc.Index)]
216						}
217						send(agent.StreamDelta{
218							Model:        chunk.Model,
219							ToolCallID:   id,
220							ToolCallName: tc.Function.Name,
221							ToolCallArgs: tc.Function.Arguments,
222						})
223					}
224	
225					if choice.Delta.Content != "" || choice.FinishReason != "" || reasoningContent != "" {
226						send(agent.StreamDelta{
227							Model:            chunk.Model,
228							Content:          choice.Delta.Content,
229							ReasoningContent: reasoningContent,
230							FinishReason:     string(choice.FinishReason),
231						})
232					} else if len(choice.Delta.ToolCalls) == 0 {
233						send(agent.StreamDelta{
234							Model:        chunk.Model,
235							FinishReason: string(choice.FinishReason),
236						})
237					}
238				} else {
239					send(agent.StreamDelta{Model: chunk.Model})
240				}
241	
242				if chunk.Usage.TotalTokens != 0 {
243					usage := tokenUsage(
244						int(chunk.Usage.PromptTokens),
245						int(chunk.Usage.CompletionTokens),
246						int(chunk.Usage.TotalTokens),
247						int(chunk.Usage.PromptTokensDetails.CachedTokens),
248					)
249					usage.Reasoning = extractReasoningTokens(chunk.Usage.RawJSON())
250					send(agent.StreamDelta{Usage: &usage})
251				}
252			}
253	
254			if err := stream.Err(); err != nil {
255				send(agent.StreamDelta{Err: classifyStreamErr(err)})
256				return
257			}
258	
259			done := agent.StreamDelta{
260				Model: responseModel,
261				Done:  true,
262			}
263			if hooks.Attempt != nil {
264				done.Attempt = hooks.Attempt(responseModel, streamCost)
265			}
266			send(done)
267		}()
268	
269		return ch, nil
270	}
